import itertools

def in_lang(w):
    if w == '0' or w == '1':
        return True
    if len(w) >= 3 and w[0] == '1':
        tail = w[1:]
        if len(tail) % 2 == 0:
            ok = True
            for i in range(0, len(tail), 2):
                if tail[i:i+2] != '01':
                    ok = False
                    break
            return ok
    return False

allw = [''.join(t) for n in range(4) for t in itertools.product('01', repeat=n)]
matches = [w for w in allw if in_lang(w)]
print(len(matches))
